 p=Path(path);assert p.is_file(),p
 rows.append(dict(id=i,url=url,titre=title,editeur=publisher,version_annee=version,date_consultation='2026-11-02',section_page=section,population=pop,limites=limits,cache_external=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),lecteur='sol_endocrinologie',read_level='section',passage_paraphrase=passage))
