add('S1','https://dam-api.bfs.admin.ch/hub/api/dam/assets/32686265/master','CIM-10-GM suisse : E14 et subdivisions','OFS','2024','Toutes les entrées E14 du catalogue local S05 ; hiérarchie et libellés','Classification suisse','Libellés locaux 2024 ; pas certification du codage hospitalier en vigueur 2026.',R/'nosology/fragments/S05.json','E14 désigne le diabète sans précision du type ; les subdivisions distinguent coma, acidocétose et atteintes rénales, oculaires, neurologiques, vasculaires, autres, multiples, non précisées et absence de complication.')
add('S3','https://classbrowser.nhs.uk/ICD-10-5TH-Edition/vol1/block-e10-e14.htm','Notes internationales E10–E14','NHS England','ICD-10 5e édition','Modificateurs avant E10, catégorie E14 et exclusions','Classification internationale','Notes internationales consultées en Europe ; ne remplacent pas règles suisses exactes.',C/'S3.html','Le coma comprend les formes hyperglycémiques, hyperosmolaires et hypoglycémiques ; les sous-codes cliniques ne prouvent pas à eux seuls le type. Grossesse et diabète néonatal sont classés ailleurs.')
inherited('S20','§SD0401n–SD0403n, p.121–128 : types, décompensation et exemples DRG','Codage hospitalier suisse','Manuel 2025 lu ; catalogue de la leçon 2024. Pas certification administrative 2026 ni outil de décision clinique.','Le traitement à l’insuline ne détermine pas le type. Le 4e caractère décrit la complication ; le 5e la décompensation. Cette dernière se juge rétrospectivement, pas sur la glycémie d’admission seule.',version='2025, publié OFS 2024')
inherited('S4','Résumé exécutif/tableau 1 ; diagnostic p.6 ; §3.1–3.2 et §4','Classification clinique mondiale, tous âges','Document 2019 ; ses proportions et hypothèses ne constituent pas une norme suisse 2026. Son exception ethnique ancienne pour le diabète cétosique ne devient pas une exclusion clinique.','La glycémie à jeun ≥7,0 mmol/L, la glycémie à 2 h ≥11,1, une HbA1c ≥6,5 % ou une glycémie aléatoire ≥11,1 avec symptômes établissent le diabète selon conditions ; l’asymptomatique demande confirmation. Le diabète non classé est une catégorie temporaire ; âge et phénotype orientent sans trancher seuls.')
inherited('S5','Stratégie type 2 ; Differential diagnosis ; Glucose target ; Special considerations in the elderly ; mesures multifactorielles','Adultes avec diabète de type 2, ou diagnostic initial à préciser','Recommandations 2023 ; la co-formulation proposée vise un sous-groupe insulinodéficient et ne remplace pas le schéma de type 1. Associations non randomisées, restrictions de remboursement historiques et doses ne sont pas généralisées.','Une insulinodéficience, la cétose, une perte de poids et une hyperglycémie sévère justifient l’insuline sans attendre le typage. Un type 2 confirmé conduit à une stratégie multifactorielle ; cible HbA1c souvent 7 %, adaptée aux hypoglycémies, fragilité et espérance de vie.')
inherited('S7','Page entière : chiffres 2022, définition, méthode, date de mise à jour','Personnes ≥15 ans, ménages privés suisses, autodéclaration','Pas incidence ni répartition valide des types ou fréquence E14 ; enquête excluant population institutionnalisée.','En 2022, 6,2 % déclarent diabète ou traitement, femmes 5,6 % et hommes 6,9 %. Le type n’est pas quantifié de façon fiable.','html',version='Page MAJ 17.03.2025, enquête 2022')
inherited('S8','§1–3 ; §9 et tableau 2 p.10–11','Conducteurs du premier groupe médical suisse','Recommandations 2025 ; conditions distinctes selon traitement et surveillance continue. Le groupe professionnel demande une évaluation propre ; ce document ne constitue pas un permis.','Le risque dépend des hypoglycémies, des complications et du traitement. À risque élevé sans surveillance continue, glycémie avant départ et au moins toutes les deux heures ; correction des valeurs basses, pas de conduite sous 4 mmol/L et attente minimale 45 minutes après correction.',version='Août 2025')
add('S10','https://pmc.ncbi.nlm.nih.gov/articles/PMC3748788/','Clinical utility of C-peptide measurement','Jones et Hattersley, Royaume-Uni','2013','Introduction ; physiologie, assay, units, blood measurement et tableau 1','Adultes insulinotraités et patients à typer','Revue ancienne ; seuils proposés dépendant du jeûne/stimulation, méthode, fonction rénale et durée. Pas intervalle universel.',C/'S10.xml','L’insuline et le peptide C sont sécrétés de manière équimolaire mais leurs concentrations périphériques ne sont pas égales : clairance hépatique et demi-vies diffèrent. L’insuffisance rénale peut élever le peptide C ; la glycémie simultanée et le contexte alimentaire sont indispensables.')
add('S11','https://pmc.ncbi.nlm.nih.gov/articles/PMC11343900/','Hyperglycaemic crises in adults with diabetes','Consensus conjoint EASD/JBDS/ADA/AACE/DTS','2024','Introduction ; §3 entier et Fig.2 inspectée ; §4 entier ; prévention et populations particulières ciblées','Adultes avec acidocétose ou état hyperosmolaire','Consensus transatlantique incluant EASD et JBDS ; pas recommandation américaine seule. Ne vaut pas protocole pédiatrique, produit exact ou prescription hospitalière individuelle.',C/'S11.xml','L’acidocétose exige diabète/hyperglycémie, cétones et acidose. L’état hyperosmolaire exige quatre critères dont glycémie ≥33,3 et osmolalité efficace >300 ou totale >320. Réhydratation, insuline, potassium et cause sont coordonnés. Le potassium <3,5 retarde l’insuline ; résolution sur cétones et pH/bicarbonate, pas trou anionique seul.')
inherited('S12','Tableau entier : fréquence des contrôles et objectifs collectifs','Organisation suisse des soins de premier recours','Document de qualité des soins 2017 ; cibles de population ne sont pas cibles individuelles et un intervalle de deux ans pour les yeux ne convient pas à toute rétinopathie.','Contrôles réguliers au moins trois fois/an, HbA1c au moins deux fois/an, examen du pied et bilan rénal annuels ; examen des yeux au moins tous les deux ans dans cette grille.',version='Révision juin, adoption août 2017')
inherited('S13','Parcours complet niveaux 1A/1B, 2 et 3 ; critères de red flags ; définition infection','Pied diabétique et ulcère en Suisse','La simplification pouls/indice du guide QCARE est confrontée à IWGDF/ESVS/SVS 2023 ; elle ne devient pas exclusion universelle de maladie artérielle.','Une plaie profonde/plantaire, la neuropathie, l’ischémie ou l’infection imposent une montée du niveau de soins. Infection systémique/rapidement progressive, ischémie critique et Charcot aigu sont des drapeaux rouges.',version='2023')
inherited('S14','Recommandations et tableaux 1–2 entiers','Diagnostic diabète/prédiabète par HbA1c','Position suisse 2011 ; symboles > historiques confrontés aux seuils ≥ OMS 2019. La borne post-charge 11,1 ne peut appartenir simultanément au prédiabète et au diabète.','La méthode doit être standardisée ; hémoglobinopathies, turnover érythrocytaire et atteintes sévères peuvent rendre l’HbA1c inadaptée. Le diagnostic rapide d’un type 1 ne doit pas attendre l’HbA1c.')
inherited('S15','Dépistage, grille de risque rénal, drapeaux rouges, algorithme thérapeutique, premières pages','Adultes diabétiques, synthèse surtout type 2','PDF publié mai 2024 malgré nom de fichier 2023. Son tableau de doses ne remplace pas la FI exacte Glucophage 2025.','Créatinine et rapport albumine/créatinine annuels ; maladie rénale chronique sur persistance au moins trois mois. Une hématurie active, baisse rapide du débit, protéinurie importante ou présentation atypique impose une autre enquête.',version='Première publication mai 2024 ; consensus 2023')
add('S17','https://pmc.ncbi.nlm.nih.gov/articles/PMC10107355/','Management of hyperosmolar hyperglycaemic state in adults','JBDS, Royaume-Uni','2023, en ligne 2022','Definition, clinical presentation, osmolality, mixed DKA/HHS et insulin timing','Adultes hospitalisés','Définitions JBDS et consensus 2024 distinctes ; correction lente, soins experts. Ne pas transposer aux enfants.',C/'S17.xml','L’hyperosmolarité peut masquer la déplétion volémique ; la correction trop rapide expose au dommage neurologique. Le parcours JBDS commence le remplissage et diffère l’insuline dans une forme sans cétose jusqu’au ralentissement de la chute glycémique.')
for i,title,gtin,version,passage in [
('S18','Baqsimi 3 mg poudre nasale','7680674650010','mars 2026','Traitement d’hypoglycémie sévère dès un an, 3 mg intranasal une fois. Réserves hépatiques de glycogène nécessaires ; hypersensibilité et phéochromocytome contre-indiqués. Pas d’adaptation rénale/hépatique, mais pas étude formelle dédiée.'),
('S19','Glucophage 500/850/1000 mg comprimés','7680260610169','octobre 2025','Début adulte 500–1000 mg/j, titration de 500 mg tous les 5–7 jours, maximum 3000 mg/j ; pour filtration 30–59, début 500/850 mg/j et maximum 1000 mg/j. Acidose, déshydratation et atteinte hypoxique aiguë interdisent le produit. Grossesse possible si indication, avec surveillance croissance ; allaitement arbitré.'),
('S23','NovoRapid 100 unités/ml, insuline aspart','7680550450024','avril 2026','Injection sous-cutanée avec repas, besoins individualisés ; administration intraveineuse possible par professionnel avec contrôle glycémie et potassium. La FI établit une compatibilité de 0,05–1 unité/ml, pas un débit de crise de 0,1 unité/kg/h.'),
('S24','Kaliumchlorid B. Braun 7,45 % et 14,9 %','7680295520907','janvier 2007','Concentrés 1 ou 2 mmol/ml, jamais non dilués. Acidose, déshydratation grave, insuffisance rénale, anurie/oligurie et hyperkaliémie figurent en contre-indications ; divergence avec l’usage syndromique de potassium dans les crises.'),
('S26','Kalium chloratum 15 % Sintetica','7680514340132','février 2024','Concentré 2 mmol/ml, dilution et perfusion lente obligatoires ; acidose, insuffisance rénale et déshydratation grave figurent aussi en contre-indications.')]:
 add(i,'https://amiko.oddb.org/fr/fi?gtin='+gtin,'Information professionnelle suisse '+title,'Swissmedic/AIPS via AmiKo',version,'Indications, posologie, contre-indications, précautions, interactions, grossesse/allaitement ; mécanisme et manipulation ciblés','Produit exact ; populations explicitées dans le texte','Ne vaut pas une autre formulation. Les débits des recommandations de crise ne sont pas attribués à la FI. Version ancienne conservée explicitement si telle que servie.',C/(i+'.txt'),passage)

